+{
+  "id": "claude",
+  "name": "Claude",
+  "description": "Claude app-server harness. Delegates Anthropic-provider turns to a local @openclaw/claude-app-server process, mirroring the codex-app-server pattern. Exposes OpenClaw dynamic tools to Claude inside the turn.",
+  "activation": {
+    "onStartup": false,
+    "onAgentHarnesses": ["claude-app-server"]
+  },
+  "configSchema": {
+    "type": "object",
+    "additionalProperties": false,
+    "properties": {
+      "appServer": {
+        "type": "object",
+        "additionalProperties": false,
+        "properties": {
+          "command": {
+            "type": "string",
+            "description": "Executable for the openclaw-claude-app-server binary. Defaults to 'openclaw-claude-app-server' on PATH."
+          },
+          "args": {
+            "type": "array",
+            "items": { "type": "string" },
+            "description": "Extra CLI args for the server."
+          },
+          "env": {
+            "type": "object",
+            "additionalProperties": { "type": "string" },
+            "description": "Extra env vars injected into the server process."
+          },
+          "approvalPolicy": {
+            "type": "string",
+            "enum": ["never", "untrusted", "on-failure", "on-request"],
+            "default": "never",
+            "description": "Codex-shaped approval policy. 'never' bypasses approval gates (the default and equivalent to the legacy bypassPermissions setting)."
+          },
+          "sandbox": {
+            "type": "string",
+            "enum": ["read-only", "workspace-write", "danger-full-access"],
+            "default": "danger-full-access",
+            "description": "Sandbox mode echoed to the server at thread/start."
+          },
+          "turnTimeoutMs": {
+            "type": "number",
+            "minimum": 1,
+            "default": 600000,
+            "description": "Hard per-turn timeout in ms."
+          },
+          "turnIdleTimeoutMs": {
+            "type": "number",
+            "minimum": 1,
+            "default": 90000,
+            "description": "Idle watchdog: fail the turn if no notification arrives for this many ms."
+          }
+        }
+      },
+      "dynamicTools": {
+        "type": "object",
+        "additionalProperties": false,
+        "properties": {
+          "exclude": {
+            "type": "array",
+            "items": { "type": "string" },
+            "default": [],
+            "description": "OpenClaw dynamic tool names to omit when projecting into Claude turns."
+          }
+        }
+      }
+    }
+  },
+  "uiHints": {
+    "appServer.approvalPolicy": {
+      "label": "Approval Policy",
+      "help": "'never' is the openclaw-default unattended posture. Switch to 'untrusted' or 'on-request' to wire the codex approval-request protocol; the plugin currently auto-declines unhandled approval requests."
+    },
+    "appServer.sandbox": {
+      "label": "Sandbox",
+      "help": "Sandbox mode echoed to the server (the server doesn't enforce this; it's informational at this layer)."
+    },
+    "dynamicTools.exclude": {
+      "label": "Dynamic Tool Excludes",
+      "advanced": true
+    }
+  }
+}
