diff --git a/extensions/claude/src/app-server/client.ts b/extensions/claude/src/app-server/client.ts
new file mode 100644
index 0000000000000..edb73e7d9a5f5
--- /dev/null
+++ b/extensions/claude/src/app-server/client.ts
@@ -0,0 +1,433 @@
+/**
+ * JSON-RPC 2.0 client over a stdio child process — talks to the
+ * @openclaw/claude-app-server binary. Bidirectional: the server can send
+ * REQUESTS to us (`item/tool/call`, approval requests) which we route to
+ * registered handlers.
+ *
+ * A single shared client is kept per host process so multiple turns share
+ * one server (cheaper than spawn-per-turn). `clearSharedClaudeAppServerClient`
+ * is called from the harness `dispose` hook on plugin teardown.
+ */
+
+import { spawn, type ChildProcess } from "node:child_process";
+import { createInterface, type Interface as ReadlineInterface } from "node:readline";
+import { embeddedAgentLog } from "openclaw/plugin-sdk/agent-harness-runtime";
+import type { JsonValue, RpcMessage, RpcNotification, RpcRequest, RpcResponse } from "./types.js";
+
+export type ClaudeAppServerStartOptions = {
+  command?: string;
+  args?: string[];
+  env?: Record<string, string | undefined>;
+};
+
+export type NotificationHandler = (notification: RpcNotification) => void;
+
+export type ServerRequestHandler = (req: {
+  id: number | string;
+  method: string;
+  params?: JsonValue;
+}) => Promise<JsonValue | undefined> | JsonValue | undefined;
+
+type PendingRequest = {
+  method: string;
+  resolve: (value: JsonValue) => void;
+  reject: (error: Error) => void;
+};
+
+const DEFAULT_COMMAND = "openclaw-claude-app-server";
+const FORCE_KILL_DELAY_MS = 2_000;
+const REQUEST_TIMEOUT_MS = 600_000;
+const STDERR_TAIL_MAX = 2_000;
+const INIT_TIMEOUT_MS = 30_000;
+
+export class ClaudeAppServerRpcError extends Error {
+  constructor(
+    message: string,
+    readonly code?: number,
+    readonly data?: JsonValue,
+    readonly method?: string,
+  ) {
+    super(message);
+    this.name = "ClaudeAppServerRpcError";
+  }
+}
+
+export class ClaudeAppServerClient {
+  private child: ChildProcess | null = null;
+  private nextId = 1;
+  private pending = new Map<number, PendingRequest>();
+  private notificationHandlers: NotificationHandler[] = [];
+  private serverRequestHandlers: ServerRequestHandler[] = [];
+  private stopped = false;
+  private initializePromise: Promise<JsonValue> | null = null;
+  private initialized = false;
+  private stderrRl: ReadlineInterface | null = null;
+  private stdoutRl: ReadlineInterface | null = null;
+  private stderrTail = "";
+  private serverInfo: { name?: string; version?: string } | null = null;
+
+  constructor(private readonly opts: ClaudeAppServerStartOptions) {}
+
+  async start(): Promise<void> {
+    if (this.initializePromise) {
+      await this.initializePromise;
+      return;
+    }
+    this.stopped = false;
+    this.initialized = false;
+    this.stderrTail = "";
+
+    const command = this.opts.command ?? DEFAULT_COMMAND;
+    const args = this.opts.args ?? [];
+    const env: NodeJS.ProcessEnv = { ...process.env, ...this.opts.env };
+
+    this.child = spawn(command, args, {
+      env,
+      stdio: ["pipe", "pipe", "pipe"],
+      detached: process.platform !== "win32",
+    });
+
+    embeddedAgentLog.info("claude-app-server: spawned", { pid: this.child.pid, command });
+
+    this.stderrRl = createInterface({ input: this.child.stderr! });
+    this.stderrRl.on("line", (line) => {
+      if (!line.trim()) return;
+      this.stderrTail = appendBoundedTail(this.stderrTail, `${line}\n`, STDERR_TAIL_MAX);
+      embeddedAgentLog.debug(`claude-app-server stderr: ${line}`);
+    });
+
+    this.stdoutRl = createInterface({ input: this.child.stdout! });
+    this.stdoutRl.on("line", (line) => this.onLine(line));
+
+    this.child.once("exit", (code, signal) => {
+      embeddedAgentLog.warn("claude-app-server: process exited", { code, signal });
+      const suffix = this.stderrTail
+        ? ` stderr=${JSON.stringify(this.stderrTail.slice(-STDERR_TAIL_MAX))}`
+        : "";
+      this.handleChildExit(
+        new Error(
+          `openclaw-claude-app-server exited (code=${formatExitValue(code)} signal=${formatExitValue(signal)})${suffix}`,
+        ),
+      );
+    });
+    this.child.stdin?.on("error", (err) => {
+      embeddedAgentLog.warn("claude-app-server: stdin error", { error: err.message });
+      this.handleChildExit(new Error(`openclaw-claude-app-server stdin error: ${err.message}`));
+    });
+
+    this.initializePromise = this.sendRequest<JsonValue>(
+      "initialize",
+      {
+        clientInfo: { name: "openclaw/extensions/claude", version: "0.1.0" },
+        capabilities: { experimentalApi: true },
+      },
+      AbortSignal.timeout(INIT_TIMEOUT_MS),
+    ).then((result) => {
+      this.initialized = true;
+      if (result && typeof result === "object" && !Array.isArray(result)) {
+        const info = (result as Record<string, unknown>).serverInfo;
+        if (info && typeof info === "object" && !Array.isArray(info)) {
+          this.serverInfo = info as { name?: string; version?: string };
+        }
+      }
+      embeddedAgentLog.info("claude-app-server: initialized", { server: this.serverInfo });
+      return result;
+    });
+
+    try {
+      await this.initializePromise;
+    } catch (err) {
+      this.initializePromise = null;
+      this.stop();
+      throw err;
+    }
+  }
+
+  getServerInfo(): { name?: string; version?: string } | null {
+    return this.serverInfo;
+  }
+
+  stop(): void {
+    if (this.stopped) return;
+    this.stopped = true;
+    const child = this.child;
+    this.child = null;
+    this.initialized = false;
+    this.initializePromise = null;
+    this.closeReaders();
+    if (!child) return;
+    child.stdin?.end();
+    child.stdin?.destroy();
+    const forceKill = setTimeout(() => {
+      try {
+        if (child.pid && process.platform !== "win32") {
+          process.kill(-child.pid, "SIGKILL");
+        } else {
+          child.kill("SIGKILL");
+        }
+      } catch {
+        /* ignore */
+      }
+    }, FORCE_KILL_DELAY_MS);
+    forceKill.unref?.();
+    child.once("exit", () => clearTimeout(forceKill));
+    child.unref?.();
+    this.rejectAll(new Error("claude-app-server stopped"));
+  }
+
+  isRunning(): boolean {
+    return this.child !== null && !this.stopped;
+  }
+
+  async request<T = JsonValue>(method: string, params?: unknown, signal?: AbortSignal): Promise<T> {
+    if (method !== "initialize") {
+      if (this.initializePromise) {
+        await this.initializePromise.catch(() => {});
+      }
+      if (!this.initialized) {
+        throw new Error("claude-app-server is not initialized");
+      }
+    }
+    return this.sendRequest<T>(method, params, signal);
+  }
+
+  notify(method: string, params?: unknown): void {
+    this.writeLine(JSON.stringify({ jsonrpc: "2.0", method, params }));
+  }
+
+  onNotification(handler: NotificationHandler): () => void {
+    this.notificationHandlers.push(handler);
+    return () => {
+      this.notificationHandlers = this.notificationHandlers.filter((h) => h !== handler);
+    };
+  }
+
+  onServerRequest(handler: ServerRequestHandler): () => void {
+    this.serverRequestHandlers.push(handler);
+    return () => {
+      this.serverRequestHandlers = this.serverRequestHandlers.filter((h) => h !== handler);
+    };
+  }
+
+  private async sendRequest<T>(method: string, params: unknown, signal?: AbortSignal): Promise<T> {
+    if (!this.child) throw new Error("claude-app-server is not running");
+    const id = this.nextId++;
+    const msg: RpcRequest = { jsonrpc: "2.0", id, method, params };
+
+    const result = await new Promise<JsonValue>((resolve, reject) => {
+      const timeout = setTimeout(() => {
+        this.pending.delete(id);
+        reject(
+          new ClaudeAppServerRpcError(`RPC ${method} timed out`, undefined, undefined, method),
+        );
+      }, REQUEST_TIMEOUT_MS);
+      const onAbort = () => {
+        clearTimeout(timeout);
+        this.pending.delete(id);
+        reject(new ClaudeAppServerRpcError(`RPC ${method} aborted`, undefined, undefined, method));
+      };
+      signal?.addEventListener("abort", onAbort, { once: true });
+      this.pending.set(id, {
+        method,
+        resolve: (value) => {
+          clearTimeout(timeout);
+          signal?.removeEventListener("abort", onAbort);
+          resolve(value);
+        },
+        reject: (error) => {
+          clearTimeout(timeout);
+          signal?.removeEventListener("abort", onAbort);
+          reject(error);
+        },
+      });
+      try {
+        this.writeLine(JSON.stringify(msg));
+      } catch (writeErr) {
+        clearTimeout(timeout);
+        signal?.removeEventListener("abort", onAbort);
+        this.pending.delete(id);
+        reject(writeErr instanceof Error ? writeErr : new Error(String(writeErr)));
+      }
+    });
+    return result as T;
+  }
+
+  private writeLine(line: string): void {
+    if (!this.child?.stdin) throw new Error("stdin unavailable — server not running");
+    this.child.stdin.write(line + "\n");
+  }
+
+  private onLine(line: string): void {
+    const trimmed = line.trim();
+    if (!trimmed) return;
+    let msg: RpcMessage;
+    try {
+      msg = JSON.parse(trimmed) as RpcMessage;
+    } catch {
+      embeddedAgentLog.warn("claude-app-server: unparseable line", {
+        preview: trimmed.slice(0, 200),
+      });
+      return;
+    }
+
+    if ("id" in msg && msg.id !== undefined && "method" in msg) {
+      void this.handleServerRequest(msg as RpcRequest);
+      return;
+    }
+    if ("id" in msg && msg.id !== undefined) {
+      const resp = msg as RpcResponse;
+      const pending = this.pending.get(resp.id as number);
+      if (!pending) {
+        embeddedAgentLog.warn("claude-app-server: unexpected response id", { id: resp.id });
+        return;
+      }
+      this.pending.delete(resp.id as number);
+      if (resp.error) {
+        pending.reject(
+          new ClaudeAppServerRpcError(
+            resp.error.message || `RPC ${pending.method} failed`,
+            resp.error.code,
+            resp.error.data,
+            pending.method,
+          ),
+        );
+      } else {
+        pending.resolve((resp.result ?? null) as JsonValue);
+      }
+      return;
+    }
+    if ("method" in msg) {
+      const notif = msg as RpcNotification;
+      for (const handler of this.notificationHandlers) {
+        try {
+          handler(notif);
+        } catch (err) {
+          embeddedAgentLog.warn("claude-app-server: notification handler threw", { error: err });
+        }
+      }
+    }
+  }
+
+  private async handleServerRequest(req: RpcRequest): Promise<void> {
+    const id = req.id!;
+    try {
+      for (const handler of this.serverRequestHandlers) {
+        const result = await handler({
+          id: id as number,
+          method: req.method,
+          params: req.params as JsonValue | undefined,
+        });
+        if (result !== undefined) {
+          this.writeLine(JSON.stringify({ jsonrpc: "2.0", id, result }));
+          return;
+        }
+      }
+      // Default decline so the server doesn't hang waiting forever.
+      this.writeLine(
+        JSON.stringify({ jsonrpc: "2.0", id, result: defaultServerRequestResponse(req.method) }),
+      );
+    } catch (err) {
+      this.writeLine(
+        JSON.stringify({
+          jsonrpc: "2.0",
+          id,
+          error: { code: -32603, message: err instanceof Error ? err.message : String(err) },
+        }),
+      );
+    }
+  }
+
+  private handleChildExit(error: Error): void {
+    if (this.child === null) return;
+    this.rejectAll(error);
+    this.closeReaders();
+    this.child = null;
+    this.initialized = false;
+    this.initializePromise = null;
+  }
+
+  private rejectAll(error: Error): void {
+    for (const [id, pending] of this.pending) {
+      this.pending.delete(id);
+      pending.reject(error);
+    }
+  }
+
+  private closeReaders(): void {
+    this.stderrRl?.close();
+    this.stderrRl = null;
+    this.stdoutRl?.close();
+    this.stdoutRl = null;
+  }
+}
+
+function defaultServerRequestResponse(method: string): JsonValue {
+  if (
+    method === "item/commandExecution/requestApproval" ||
+    method === "item/fileChange/requestApproval"
+  ) {
+    return { decision: "decline", reason: "no approval handler registered" };
+  }
+  if (method === "item/permissions/requestApproval") {
+    return { permissions: {}, scope: "turn" };
+  }
+  if (method === "item/tool/call") {
+    return {
+      contentItems: [{ type: "inputText", text: "no dynamic-tool handler registered" }],
+      success: false,
+    };
+  }
+  return {};
+}
+
+function appendBoundedTail(current: string, next: string, maxLength: number): string {
+  const combined = current + next;
+  return combined.length > maxLength ? combined.slice(combined.length - maxLength) : combined;
+}
+
+function formatExitValue(value: unknown): string {
+  if (value === null || value === undefined) return "null";
+  if (typeof value === "string" || typeof value === "number") return String(value);
+  return "unknown";
+}
+
+// ─── Shared client lifecycle ────────────────────────────────────────────────
+
+let sharedClient: ClaudeAppServerClient | null = null;
+let sharedClientKey = "";
+
+export function getSharedClaudeAppServerClient(
+  opts: ClaudeAppServerStartOptions,
+): ClaudeAppServerClient {
+  // Spawn options form a key; if it changes we tear down the old client and
+  // start fresh. This keeps reconfiguration cheap from the operator's side.
+  const key = JSON.stringify({
+    command: opts.command ?? DEFAULT_COMMAND,
+    args: opts.args ?? [],
+    env: opts.env ?? null,
+  });
+  if (!sharedClient || !sharedClient.isRunning() || sharedClientKey !== key) {
+    if (sharedClient) {
+      try {
+        sharedClient.stop();
+      } catch {
+        /* ignore */
+      }
+    }
+    sharedClient = new ClaudeAppServerClient(opts);
+    sharedClientKey = key;
+  }
+  return sharedClient;
+}
+
+export async function clearSharedClaudeAppServerClient(): Promise<void> {
+  if (sharedClient) {
+    try {
+      sharedClient.stop();
+    } catch {
+      /* ignore */
+    }
+    sharedClient = null;
+    sharedClientKey = "";
+  }
+}
diff --git a/extensions/claude/src/app-server/dynamic-tools.ts b/extensions/claude/src/app-server/dynamic-tools.ts
new file mode 100644
index 0000000000000..729d71849ae81
--- /dev/null
+++ b/extensions/claude/src/app-server/dynamic-tools.ts
@@ -0,0 +1,284 @@
+/**
+ * Projects OpenClaw's tool registry into the `DynamicToolSpec[]` shape the
+ * codex-shaped server consumes, and dispatches `item/tool/call` requests
+ * back to the underlying `AnyAgentTool` instances.
+ *
+ * Native hook relay + telemetry are wired through the same plugin-SDK
+ * helpers codex uses:
+ *   - `wrapToolWithBeforeToolCallHook` fires OpenClaw `BeforeToolCall` hooks
+ *     around each tool execution so plugin observers see Claude's calls.
+ *   - `runAgentHarnessAfterToolCallHook` fires the `AfterToolCall` hook with
+ *     timing + result.
+ *   - `extractToolResultMediaArtifact` + `filterToolResultMediaUrls` lift
+ *     media URLs and audio-as-voice flags out of tool results into the
+ *     telemetry channel the run-attempt copies into AttemptResult.
+ *   - `isMessagingTool` + `isMessagingToolSendAction` detect when Claude
+ *     called OpenClaw's `message` tool so we can populate
+ *     `didSendViaMessagingTool` and the messagingToolSent* fields.
+ */
+
+import {
+  extractToolResultMediaArtifact,
+  filterToolResultMediaUrls,
+  HEARTBEAT_RESPONSE_TOOL_NAME,
+  isMessagingTool,
+  isMessagingToolSendAction,
+  isToolWrappedWithBeforeToolCallHook,
+  normalizeHeartbeatToolResponse,
+  runAgentHarnessAfterToolCallHook,
+  setBeforeToolCallDiagnosticsEnabled,
+  wrapToolWithBeforeToolCallHook,
+  type AnyAgentTool,
+  type EmbeddedRunAttemptParams,
+  type HeartbeatToolResponse,
+  type MessagingToolSend,
+} from "openclaw/plugin-sdk/agent-harness-runtime";
+import type {
+  DynamicToolCallOutputContentItem,
+  DynamicToolCallParams,
+  DynamicToolCallResponse,
+  DynamicToolSpec,
+  JsonValue,
+} from "./types.js";
+
+export type ClaudeDynamicToolHookContext = {
+  agentId?: string;
+  config?: EmbeddedRunAttemptParams["config"];
+  sessionId?: string;
+  sessionKey?: string;
+  runId?: string;
+  channelId?: string;
+};
+
+export type ClaudeDynamicToolTelemetry = {
+  didSendViaMessagingTool: boolean;
+  messagingToolSentTexts: string[];
+  messagingToolSentMediaUrls: string[];
+  messagingToolSentTargets: MessagingToolSend[];
+  heartbeatToolResponse?: HeartbeatToolResponse;
+  toolMediaUrls: string[];
+  toolAudioAsVoice: boolean;
+};
+
+export type ClaudeDynamicToolBridge = {
+  specs: DynamicToolSpec[];
+  telemetry: ClaudeDynamicToolTelemetry;
+  handleToolCall: (
+    params: DynamicToolCallParams,
+    options?: { signal?: AbortSignal },
+  ) => Promise<DynamicToolCallResponse>;
+};
+
+export function createClaudeDynamicToolBridge(params: {
+  tools: AnyAgentTool[];
+  signal?: AbortSignal;
+  excludeNames?: Iterable<string>;
+  hookContext?: ClaudeDynamicToolHookContext;
+}): ClaudeDynamicToolBridge {
+  const excluded = new Set([...(params.excludeNames ?? [])].map((n) => n.trim()).filter(Boolean));
+  const hookContext = params.hookContext ?? {};
+  // Wrap each tool so OpenClaw `BeforeToolCall` hooks fire around it. The
+  // runtime's existing wrapping (if any) is preserved; we only attach when
+  // missing.
+  const wrappedTools = params.tools
+    .filter((tool) => tool?.name && !excluded.has(tool.name))
+    .map((tool) => {
+      if (isToolWrappedWithBeforeToolCallHook(tool)) {
+        setBeforeToolCallDiagnosticsEnabled(tool, false);
+        return tool;
+      }
+      return wrapToolWithBeforeToolCallHook(tool, hookContext, { emitDiagnostics: false });
+    });
+  const toolsByName = new Map(wrappedTools.map((t) => [t.name, t]));
+  const specs: DynamicToolSpec[] = wrappedTools.map((tool) => ({
+    name: tool.name,
+    description: tool.description ?? "",
+    // TypeBox schemas are JSON-Schema-shaped; ship verbatim.
+    inputSchema: (tool.parameters ?? { type: "object", additionalProperties: true }) as JsonValue,
+  }));
+  const telemetry: ClaudeDynamicToolTelemetry = {
+    didSendViaMessagingTool: false,
+    messagingToolSentTexts: [],
+    messagingToolSentMediaUrls: [],
+    messagingToolSentTargets: [],
+    toolMediaUrls: [],
+    toolAudioAsVoice: false,
+  };
+
+  async function handleToolCall(
+    call: DynamicToolCallParams,
+    options?: { signal?: AbortSignal },
+  ): Promise<DynamicToolCallResponse> {
+    const tool = toolsByName.get(call.tool);
+    if (!tool) return errorResponse(`Unknown openclaw tool: ${call.tool}`);
+    const callerSignal = options?.signal ?? params.signal;
+    const args = (call.arguments ?? {}) as Record<string, unknown>;
+    const startedAt = Date.now();
+    try {
+      const preparedArgs = tool.prepareArguments ? tool.prepareArguments(args) : args;
+      const result = await tool.execute(call.callId, preparedArgs, callerSignal);
+      const isError = isResultError(result);
+      collectTelemetry({ telemetry, toolName: tool.name, args, result, isError });
+      void runAgentHarnessAfterToolCallHook({
+        toolName: tool.name,
+        toolCallId: call.callId,
+        runId: hookContext.runId,
+        agentId: hookContext.agentId,
+        sessionId: hookContext.sessionId,
+        sessionKey: hookContext.sessionKey,
+        channelId: hookContext.channelId,
+        startArgs: args,
+        result,
+        startedAt,
+      });
+      return {
+        contentItems: projectContentItems(result),
+        success: !isError,
+      };
+    } catch (err) {
+      collectTelemetry({ telemetry, toolName: tool.name, args, result: undefined, isError: true });
+      const message = err instanceof Error ? err.message : String(err);
+      void runAgentHarnessAfterToolCallHook({
+        toolName: tool.name,
+        toolCallId: call.callId,
+        runId: hookContext.runId,
+        agentId: hookContext.agentId,
+        sessionId: hookContext.sessionId,
+        sessionKey: hookContext.sessionKey,
+        channelId: hookContext.channelId,
+        startArgs: args,
+        error: message,
+        startedAt,
+      });
+      return errorResponse(`Tool execution failed: ${message}`);
+    }
+  }
+
+  return { specs, telemetry, handleToolCall };
+}
+
+// ─── Telemetry ──────────────────────────────────────────────────────────────
+
+function collectTelemetry(params: {
+  telemetry: ClaudeDynamicToolTelemetry;
+  toolName: string;
+  args: Record<string, unknown>;
+  result: unknown;
+  isError: boolean;
+}): void {
+  if (!params.isError && params.toolName === HEARTBEAT_RESPONSE_TOOL_NAME) {
+    const response = normalizeHeartbeatToolResponse(
+      (params.result as { details?: unknown } | undefined)?.details,
+    );
+    if (response) params.telemetry.heartbeatToolResponse = response;
+  }
+  if (!params.isError && params.result) {
+    const media = extractToolResultMediaArtifact(params.result);
+    if (media) {
+      const mediaUrls = filterToolResultMediaUrls(params.toolName, media.mediaUrls, params.result);
+      const seen = new Set(params.telemetry.toolMediaUrls);
+      for (const url of mediaUrls) {
+        if (!seen.has(url)) {
+          seen.add(url);
+          params.telemetry.toolMediaUrls.push(url);
+        }
+      }
+      if (media.audioAsVoice) params.telemetry.toolAudioAsVoice = true;
+    }
+  }
+  if (!isMessagingTool(params.toolName)) return;
+  if (!isMessagingToolSendAction(params.toolName, params.args)) return;
+  params.telemetry.didSendViaMessagingTool = true;
+  const text = readFirstString(params.args, ["text", "message", "body", "content"]);
+  if (text) params.telemetry.messagingToolSentTexts.push(text);
+  const mediaUrls = collectArgMediaUrls(params.args);
+  params.telemetry.messagingToolSentMediaUrls.push(...mediaUrls);
+  params.telemetry.messagingToolSentTargets.push({
+    tool: params.toolName,
+    provider: readFirstString(params.args, ["provider", "channel"]) ?? params.toolName,
+    accountId: readFirstString(params.args, ["accountId", "account_id"]),
+    to: readFirstString(params.args, ["to", "target", "recipient"]),
+    threadId: readFirstString(params.args, ["threadId", "thread_id", "messageThreadId"]),
+    ...(text ? { text } : {}),
+    ...(mediaUrls.length > 0 ? { mediaUrls } : {}),
+  } as MessagingToolSend);
+}
+
+// ─── Result projection ──────────────────────────────────────────────────────
+
+function projectContentItems(result: unknown): DynamicToolCallOutputContentItem[] {
+  if (!result || typeof result !== "object" || Array.isArray(result)) {
+    return [{ type: "inputText", text: String(result) }];
+  }
+  const obj = result as Record<string, unknown>;
+  const items: DynamicToolCallOutputContentItem[] = [];
+  const content = obj.content;
+  if (typeof content === "string") {
+    items.push({ type: "inputText", text: content });
+  } else if (Array.isArray(content)) {
+    for (const block of content) {
+      if (!block || typeof block !== "object") continue;
+      const b = block as Record<string, unknown>;
+      if (b.type === "text" && typeof b.text === "string") {
+        items.push({ type: "inputText", text: b.text });
+      } else if (b.type === "image_url" && typeof b.image_url === "string") {
+        items.push({ type: "inputImage", imageUrl: b.image_url });
+      } else if (b.type === "image" && typeof b.url === "string") {
+        items.push({ type: "inputImage", imageUrl: b.url as string });
+      }
+    }
+  }
+  if (items.length === 0) {
+    if (typeof obj.text === "string") {
+      items.push({ type: "inputText", text: obj.text });
+    } else {
+      items.push({ type: "inputText", text: stringify(obj) });
+    }
+  }
+  return items;
+}
+
+// ─── Helpers ────────────────────────────────────────────────────────────────
+
+function isResultError(result: unknown): boolean {
+  if (!result || typeof result !== "object" || Array.isArray(result)) return false;
+  const obj = result as Record<string, unknown>;
+  return obj.isError === true || obj.is_error === true;
+}
+
+function readFirstString(
+  args: Record<string, unknown>,
+  keys: readonly string[],
+): string | undefined {
+  for (const key of keys) {
+    const v = args[key];
+    if (typeof v === "string" && v.length > 0) return v;
+  }
+  return undefined;
+}
+
+function collectArgMediaUrls(args: Record<string, unknown>): string[] {
+  const urls: string[] = [];
+  for (const key of ["mediaUrls", "mediaUrl", "imageUrls", "imageUrl", "url", "urls"]) {
+    const v = args[key];
+    if (typeof v === "string") urls.push(v);
+    else if (Array.isArray(v)) {
+      for (const item of v) {
+        if (typeof item === "string") urls.push(item);
+      }
+    }
+  }
+  return urls;
+}
+
+function stringify(value: unknown): string {
+  try {
+    return JSON.stringify(value);
+  } catch {
+    return String(value);
+  }
+}
+
+function errorResponse(message: string): DynamicToolCallResponse {
+  return { contentItems: [{ type: "inputText", text: message }], success: false };
+}
diff --git a/extensions/claude/src/app-server/native-tools-coverage.test.ts b/extensions/claude/src/app-server/native-tools-coverage.test.ts
new file mode 100644
index 0000000000000..fe40b37d09adf
--- /dev/null
+++ b/extensions/claude/src/app-server/native-tools-coverage.test.ts
@@ -0,0 +1,108 @@
+/**
+ * Contract test for NATIVE_TOOLS_FULL_SET (run-attempt.ts).
+ *
+ * The list of native tool names we project OpenClaw's policy onto must keep
+ * up with @anthropic-ai/claude-agent-sdk. The SDK enumerates each native
+ * tool by exporting an `*Input` interface in `sdk-tools.d.ts` (e.g.
+ * `BashInput`, `WebFetchInput`, `TodoWriteInput`). This test reads that
+ * file, extracts every exported `*Input` interface, normalizes the SDK's
+ * naming quirks (e.g. `FileEditInput` → `Edit`), and asserts every one is
+ * present in `NATIVE_TOOLS_FULL_SET`.
+ *
+ * When the SDK adds a new native tool, this test fails until someone:
+ *   1. Looks at the new tool, decides whether OpenClaw policy should block
+ *      it under `disableTools` / restrictive `toolsAllow`.
+ *   2. Adds it to `NATIVE_TOOLS_FULL_SET` (or to `SDK_INPUT_TO_TOOL_NAME`
+ *      if the SDK's interface name differs from the runtime tool name).
+ *
+ * The reverse direction is intentionally not asserted: NATIVE_TOOLS_FULL_SET
+ * may include tool names that don't have `*Input` interfaces (e.g.
+ * `BashOutput`, `KillBash`, `MultiEdit` are extended SDK tools per the
+ * claude_code preset but lack a dedicated typed input shape). Over-blocking
+ * is safe; under-blocking is not.
+ */
+
+import { readFileSync } from "node:fs";
+import * as path from "node:path";
+import { fileURLToPath } from "node:url";
+import { describe, expect, it } from "vitest";
+import { NATIVE_TOOLS_FULL_SET } from "./run-attempt.js";
+
+// Map from SDK's interface base name (without `Input`) to the runtime tool
+// name we ship to `sdkOptions.disallowedTools`. Most are identity; a few
+// SDK interfaces use a `File*` prefix that doesn't match the tool name.
+const SDK_INPUT_TO_TOOL_NAME: Record<string, string> = {
+  FileEdit: "Edit",
+  FileRead: "Read",
+  FileWrite: "Write",
+  // McpInput is a generic dispatch type, not a tool the model invokes.
+  Mcp: "__omit__",
+};
+
+function findSdkToolsDts(): string {
+  const here = path.dirname(fileURLToPath(import.meta.url));
+  // Walk up to repo root looking for node_modules/@anthropic-ai/claude-agent-sdk.
+  let dir = here;
+  for (let depth = 0; depth < 10; depth++) {
+    const candidate = path.join(
+      dir,
+      "node_modules",
+      "@anthropic-ai",
+      "claude-agent-sdk",
+      "sdk-tools.d.ts",
+    );
+    try {
+      readFileSync(candidate, "utf8");
+      return candidate;
+    } catch {
+      // continue walking up
+    }
+    const parent = path.dirname(dir);
+    if (parent === dir) break;
+    dir = parent;
+  }
+  throw new Error(
+    "could not locate @anthropic-ai/claude-agent-sdk/sdk-tools.d.ts from this test file; " +
+      "check that the SDK is installed in node_modules",
+  );
+}
+
+function extractSdkInputInterfaces(source: string): string[] {
+  // Match `export interface <Name>Input` declarations and capture `<Name>`.
+  // Use a non-greedy match for safety.
+  const matches = source.matchAll(/^export interface ([A-Z][A-Za-z0-9]*)Input\b/gm);
+  const names: string[] = [];
+  for (const m of matches) names.push(m[1] as string);
+  return [...new Set(names)].sort();
+}
+
+function sdkInputToToolName(sdkInterfaceBase: string): string | null {
+  const mapped = SDK_INPUT_TO_TOOL_NAME[sdkInterfaceBase];
+  if (mapped === "__omit__") return null;
+  return mapped ?? sdkInterfaceBase;
+}
+
+describe("native-tools coverage vs @anthropic-ai/claude-agent-sdk", () => {
+  it("every exported *Input in sdk-tools.d.ts maps to a known native tool", () => {
+    const dtsPath = findSdkToolsDts();
+    const source = readFileSync(dtsPath, "utf8");
+    const sdkInputBases = extractSdkInputInterfaces(source);
+    expect(sdkInputBases.length).toBeGreaterThan(0);
+
+    const known = new Set<string>(NATIVE_TOOLS_FULL_SET);
+    const missing: string[] = [];
+    for (const base of sdkInputBases) {
+      const toolName = sdkInputToToolName(base);
+      if (toolName === null) continue;
+      if (!known.has(toolName)) missing.push(`${base}Input → ${toolName}`);
+    }
+
+    expect(
+      missing,
+      `The SDK exports these *Input types that NATIVE_TOOLS_FULL_SET doesn't cover.\n` +
+        `Either add the tool name to NATIVE_TOOLS_FULL_SET, or — if the SDK interface\n` +
+        `name differs from the runtime tool name — extend SDK_INPUT_TO_TOOL_NAME in\n` +
+        `this test file:\n  ${missing.join("\n  ")}`,
+    ).toEqual([]);
+  });
+});
diff --git a/extensions/claude/src/app-server/run-attempt.ts b/extensions/claude/src/app-server/run-attempt.ts
